mapper.select:
SELECT a.id, a.content, a.create_date, a.modify_date, u.username AS author_username, a.question_id, (SELECT COUNT(*) FROM answer_voter av WHERE av.answer_id = a.id) AS voter_count FROM answer a LEFT JOIN site_user u ON a.author_id = u.id WHERE a.question_id = #{questionId}
ORDER BY voter_count DESC, a.id DESC ORDER BY a.id DESC
LIMIT #{limit} OFFSET #{offset}
